item.content:encoded:
/* NAV */

@media (min-width: 769px) {
  .main-navigation .menu>.menu-item>a::after {
    content: "";
    position: absolute;
    right: 0;
    left: 50%;
    bottom: 15px;
    -webkit-transform: translate3d(-50%, 0, 0);
    transform: translate3d(-50%, 0, 0);

    display: block;
    width: 0;
    height: 1px;

    background-color: rgba(0, 0, 0, 0.25);
    ;
    transition: 0.3s width ease;
  }

  .main-navigation .menu>.menu-item.current-menu-item>a::after,
  .main-navigation .menu>.menu-item.current-menu-ancestor>a::after,
  .main-navigation .menu>.menu-item>a:hover::after {
    width: 50%;
  }
}

#site-navigation .main-nav>ul>li>a {
border-left: 2px solid white;
}

#site-navigation ul ul {
	box-shadow: 0 3px 6px 0 rgba(0, 0, 0, 0.4)
}

#site-navigation ul ul li {
	border-bottom:1px solid rgba(0,0,0,0.1);
}
#site-navigation ul ul li:last-child {
	border-bottom:none;
}

nav#generate-slideout-menu .main-nav > ul > li:first-child {
    border-top: 1px solid rgba(0,0,0,0.2);
}

nav#generate-slideout-menu .main-nav > ul > li {
    border-bottom: 1px solid rgba(0,0,0,0.2);
}

nav#generate-slideout-menu .main-nav > ul > li > ul > li:not(:last-child) {
    border-bottom: 1px solid rgba(255,255,255,0.2);
}

/* MOBILE HEADER/NAV STYLE */

@media(max-width: 768px) {
    nav#mobile-menu-control-wrapper {
margin-top:24px;  
border-radius: 6px;
border: 1px solid #ccc;
padding: 0 12px;
			background-color:white;
    }
}

@media(max-width: 768px) { 
.site-header .inside-header {
    flex-direction: column;
    justify-content: center;
}
}

.site-header {
	background-image: linear-gradient(135deg, #fff 40%, #f8f8f8 40% );
}

#mobile-header .inside-navigation {
	padding: 9px 3px;
}

iframe {
    border: 2px solid white;
    display:block;
}
/* OTHER */


hr {
	margin:27px 0;
}

.ital {
	font-style: italic;
}

ul, ol {
	margin-left: 2.5em;
	margin-bottom: .75em;
}
p:last-child,ul:last-child,ol:last-child {
	margin-bottom: 0;
}

/* TABLE */

p:has(+ ol),
p:has(+ ul) {
    margin-bottom: .75rem;
}

table, th, td {
	border: 1px solid lightgrey !important;
}
th {
	background-color:#eee;
}
th, td {
	font-size: .9em;
	text-align: left;
	padding: 5px;
}


/* BIO TEMPLATE */

.bio h2 {
  font-size: 1.1em;
  padding-bottom: .25em;
  margin-bottom: .25em;
  border-bottom: 2px solid #f2f2f2;
}

.bio h2:not(:first-of-type) {
  margin-top: 1.25em;
}

.wp-block-quote p {
    font-size: 0.9em;
    line-height: 2;
	  font-style: normal;
}

.wp-block-quote {
  margin-bottom: .25em
}
